'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function pyrepr(value){if(value===null)return 'None';if(value===true)return 'True';if(value===false)return 'False';if(Array.isArray(value))return '['+value.map(pyrepr).join(', ')+']';if(typeof value==='object')return '{'+Object.entries(value).map(([k,v])=>JSON.stringify(k)+': '+pyrepr(v)).join(', ')+'}';return JSON.stringify(value);}
const uiIcons={"home": "<path d=\"m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z\"/>", "path": "<circle cx=\"6\" cy=\"5\" r=\"2\"/><circle cx=\"18\" cy=\"19\" r=\"2\"/><path d=\"M8 5h8a4 4 0 0 1 0 8H8a4 4 0 0 0 0 8h8\"/>", "projects": "<rect x=\"3\" y=\"7\" width=\"18\" height=\"14\" rx=\"2\"/><path d=\"M8 7V4a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v3M3 12h18M10 12v3h4v-3\"/>", "review": "<path d=\"M3 10a9 9 0 1 1 2 8M3 4v6h6M12 7v5l3 2\"/>", "journal": "<path d=\"M5 3h13a1 1 0 0 1 1 1v17H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2ZM3 17h16M8 7h7M8 11h5\"/>", "settings": "<path d=\"m10 3-.6 2.3-2 .9-2.1-.7-2 3.5L5 10.6v2.2l-1.7 1.6 2 3.5 2.1-.7 2 .9L10 21h4l.6-2.9 2-.9 2.1.7 2-3.5-1.7-1.6v-2.2l1.7-1.6-2-3.5-2.1.7-2-.9L14 3Z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/>", "game": "<rect x=\"2\" y=\"7\" width=\"20\" height=\"12\" rx=\"4\"/><path d=\"M7 10v6M4 13h6M16 11h.01M19 15h.01M9 7V4h6\"/>", "chart": "<path d=\"M4 3v18h17M8 16v-4M13 16V7M18 16V4\"/>", "library": "<rect x=\"3\" y=\"4\" width=\"5\" height=\"17\" rx=\"1\"/><rect x=\"9\" y=\"4\" width=\"5\" height=\"17\" rx=\"1\"/><path d=\"m15 5 4-1 4 16-4 1ZM5 8h1M11 8h1\"/>", "code": "<path d=\"m8 5-6 7 6 7m8-14 6 7-6 7M14 3l-4 18\"/>"};
function icon(name){return '<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(uiIcons[name]||uiIcons.code)+'</svg>';}
const KEY='forge-progress-v1',RECOVERY_PREFIX=KEY+'-recovery-',SNAPSHOT_KEY='forge-snapshots-v1',LAST_EXPORT_KEY='forge-last-export',BACKUP_SNOOZE_KEY='forge-backup-snooze',TAB_KEY='forge-tab-signal';
const SNAPSHOT_LIMIT=5,HOUR=3600000,DAY=24*HOUR,SNAPSHOT_SPACING=6*HOUR,BACKUP_REMINDER_AFTER=7*DAY,BACKUP_SNOOZE=3*DAY;
const emptyState=()=>({version:1,completed:{},drafts:{},notes:{},assisted:{},hints:{},explanations:{},ratings:{},scratch:'',projectChecks:{},labChecks:{},labNotes:{},evidence:{},reviews:{},events:[],timerMinutes:45});
let state=emptyState(), curriculum, handbook, lessons=[], weeks=[], current=null, worker=null, runTimeout, passedCode=null, rating=null, lastRun=null, elapsed=0, clock=null, timerRunning=false, saveFailed=false, saveBlocked=false, progressUnreadable=false, lastSnapshotAt=0;
function recoveryKeys(){const keys=[];try{for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key.startsWith(RECOVERY_PREFIX))keys.push(key);}}catch{}return keys.sort();}
/* A record that cannot be read is copied aside first, so the next save can never destroy it. If the copy fails, saving stops and the record stays where it is. */
function readSavedProgress(){let raw=null;try{raw=localStorage.getItem(KEY);}catch{return;}if(raw===null)return;let old=null;try{old=JSON.parse(raw);}catch{}if(old&&typeof old==='object'&&old.version===1){state={...emptyState(),...old};return;}progressUnreadable=true;try{if(!recoveryKeys().some(key=>localStorage.getItem(key)===raw))localStorage.setItem(RECOVERY_PREFIX+Date.now(),raw);}catch{saveBlocked=true;}}
readSavedProgress();
/* The main record always wins storage space: snapshots are dropped, oldest first, to make room for it. */
function writeProgress(){const raw=JSON.stringify(state);try{localStorage.setItem(KEY,raw);}catch(error){const original=readSnapshots(),list=[...original];while(list.length){list.shift();writeSnapshots([...list]);try{localStorage.setItem(KEY,raw);return;}catch{}}writeSnapshots(original);throw error;}}
function save(){if(saveBlocked)return;try{writeProgress();if(saveFailed){saveFailed=false;toast('Saving is working again.');}takeSnapshot();}catch{if(!saveFailed){saveFailed=true;toast('Browser storage is unavailable. Export a backup to keep your work.');}}}
function readSnapshots(){try{const list=JSON.parse(localStorage.getItem(SNAPSHOT_KEY));return Array.isArray(list)?list.filter(s=>s&&Number.isFinite(s.at)&&s.state&&typeof s.state==='object'):[];}catch{return [];}}
function writeSnapshots(list){while(list.length){try{localStorage.setItem(SNAPSHOT_KEY,JSON.stringify(list));return true;}catch{list.shift();}}try{localStorage.removeItem(SNAPSHOT_KEY);}catch{}return false;}
function hasProgress(){return Object.keys(state.completed).length+Object.keys(state.drafts).length>0;}
function takeSnapshot(force=false){const now=Date.now();if(saveBlocked||!hasProgress()||(!force&&now-lastSnapshotAt<SNAPSHOT_SPACING))return;lastSnapshotAt=now;const list=readSnapshots(),raw=JSON.stringify(state),latest=list[list.length-1];if(latest&&JSON.stringify(latest.state)===raw)return;writeSnapshots([...list,{at:now,state:JSON.parse(raw)}].slice(-SNAPSHOT_LIMIT));}
function restoreSnapshot(at){const snapshot=readSnapshots().find(s=>s.at===at);if(!snapshot)return toast('That snapshot is no longer available.');const raw=JSON.stringify(snapshot.state);return importBackup({size:raw.length,text:async()=>raw});}
/* Persistent banners above the page, for anything that should not vanish like a toast. */
const notices=new Map();
function renderNotices(){const bar=$('#notices');if(bar)bar.innerHTML=[...notices].map(([id,n])=>`<div class="notice ${n.tone}" role="${n.tone==='warn'?'alert':'status'}"><p>${esc(n.text)}</p><div class="notice-actions">${n.actions||''}<button class="notice-dismiss" data-notice-dismiss="${id}">Dismiss</button></div></div>`).join('');}
function showNotice(id,tone,text,actions=''){notices.set(id,{tone,text,actions});renderNotices();}
function clearNotice(id){if(notices.delete(id))renderNotices();}
function showRecoveryNotice(){if(progressUnreadable)showNotice('recovery','warn',saveBlocked?'Your saved progress could not be read, and there was no room to copy it aside. Saving is paused so nothing gets overwritten. Open settings to download the damaged data or restore a snapshot.':'Your saved progress could not be read, so Forge started empty. Nothing was lost: the damaged data was copied aside. Open settings to restore a snapshot or download that copy.','<a class="btn small" href="#settings">Open settings</a>');}
function lastExportTime(){try{return Number(localStorage.getItem(LAST_EXPORT_KEY))||0;}catch{return 0;}}
function lastBackupText(){const last=lastExportTime();return last?'Last backup from this browser: '+new Date(last).toLocaleString():'No backup exported from this browser yet.';}
function checkBackupReminder(){if(!hasProgress())return;const now=Date.now(),last=lastExportTime(),since=last||Math.min(now,...state.events.map(e=>e.at));let snoozed=0;try{snoozed=Number(localStorage.getItem(BACKUP_SNOOZE_KEY))||0;}catch{}if(now-since<=BACKUP_REMINDER_AFTER||now<snoozed)return;const days=Math.floor((now-since)/DAY);showNotice('backup','gentle',(last?`It has been ${days} days since your last backup.`:`You have ${days} days of progress and no backup yet.`)+' Exporting takes a few seconds and keeps your work safe if this browser’s data is cleared.','<button class="btn small" data-action="export">Export backup ↓</button>');}
function exportBackup(){download('forge-progress-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json');try{localStorage.setItem(LAST_EXPORT_KEY,String(Date.now()));}catch{}clearNotice('backup');if($('#last-backup'))$('#last-backup').textContent=lastBackupText();}
function dismissNotice(id){if(id==='backup'){try{localStorage.setItem(BACKUP_SNOOZE_KEY,String(Date.now()+BACKUP_SNOOZE));}catch{}}clearNotice(id);}
/* Two tabs each hold their own copy of state, and the last save wins. Tabs announce themselves through localStorage, which fires a storage event in every other tab. A closing tab stops answering, or the recount it triggers would report it as still open. */
let tabLeaving=false;
function signalTabs(type){try{localStorage.setItem(TAB_KEY,`${type}:${Date.now()}:${Math.random()}`);}catch{}}
function warnOtherTab(){if(!notices.has('stale'))showNotice('tabs','warn','Forge is open in another tab. Each tab saves its own copy, so use one at a time to avoid overwriting your work.');}
function handleStorageEvent(e){if(tabLeaving)return;if(e.key===KEY&&e.newValue!==null){clearNotice('tabs');showNotice('stale','warn','Another tab just saved newer progress. Reload this tab before you continue, or saving here could overwrite that work.','<button class="btn small" data-safety="reload">Reload this tab</button>');}if(e.key===TAB_KEY&&e.newValue){const [type]=e.newValue.split(':');if(type==='ping'){warnOtherTab();signalTabs('here');}if(type==='here')warnOtherTab();if(type==='bye'){clearNotice('tabs');signalTabs('ping');}}}
window.addEventListener('storage',handleStorageEvent);
window.addEventListener('pagehide',()=>{tabLeaving=true;signalTabs('bye');});
window.addEventListener('pageshow',e=>{if(e.persisted){tabLeaving=false;signalTabs('ping');}});
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function download(name,body,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function weekStart(){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return d.getTime();}
function weeklyEvents(){return state.events.filter(e=>e.at>=weekStart());}
const isCore=l=>!l.track;
function coreLessons(){return lessons.filter(isCore);}
function nextLesson(){return lessons.find(l=>isCore(l)&&!state.completed[l.id])||coreLessons().at(-1);}
function nextHashAfter(l){const n=lessons[l.id];if(l.track)return n&&n.chapter===l.chapter?'#lesson/'+n.id:'#quests/'+l.chapter;return n&&isCore(n)?'#lesson/'+n.id:'#projects';}
function countCompleted(){return coreLessons().filter(l=>state.completed[l.id]).length;}
function independent(){return Object.values(state.completed).filter(c=>!c.assisted).length;}
function dueLessons(){return lessons.filter(l=>{const c=state.completed[l.id];return c&&((state.reviews[l.id]?.due||c.due||Infinity)<=Date.now());});}
function updateNav(page){document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const n=Math.min(4,weeklyEvents().length);$('#side-dots').innerHTML=[0,1,2,3].map(i=>`<i class="${i<n?'done':''}"></i>`).join('');$('#breadcrumb').textContent=({home:'Your workspace',path:'Learning path',projects:'Project workshop',review:'Skill review',journal:'Your notebook',settings:'Preferences & backup',lesson:'Practice session',quests:'Quest book'})[page]||'Your workspace';}
function header(title,sub,right=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${right}</div>`;}
function progressForWeek(w){return lessons.filter(l=>isCore(l)&&l.week===w&&state.completed[l.id]).length;}
function renderHomeOriginal(){const next=nextLesson(),done=countCompleted(),events=weeklyEvents(),date=new Date().toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric'});const last=Math.max(0,...state.events.map(e=>e.at));return `${header('Welcome to your workshop.','A little practice today. A little more confidence tomorrow.',`<span class="date-label">${date}</span>`)}${last&&Date.now()-last>4*86400000?'<div class="resume-note">Welcome back. Nothing is lost. Start with a short skill review, or pick up your next session.</div>':''}<section class="hero"><div><span class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</span><h2>Less watching.<br>More building.</h2><p>Turn “I can follow along” into “I can build this.”<br>A guided path through Python, one small win at a time.</p><a class="btn primary" href="#lesson/${next.id}">${done?'Continue your journey':'Let’s build something'} <span>↗︎</span></a></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="code-tile"><em>def</em> build_confidence():<br>&nbsp; practice = <em>True</em><br>&nbsp; <em>return</em> small_wins</div><div class="floating-tag"><span>✓︎</span> You made that work.</div></div></section><div class="stats"><div class="stat"><span class="stat-icon">⌁</span><div><strong>${done}<span> / ${coreLessons().length}</span></strong><p>Sessions completed</p></div></div><div class="stat"><span class="stat-icon">◇</span><div><strong>${independent()}</strong><p>Independent completions</p></div></div><div class="stat"><span class="stat-icon">↻︎</span><div><strong>${dueLessons().length}</strong><p>Skills ready to revisit</p></div></div></div><div class="dashboard-grid"><div><div class="section-title"><h2>Your next small win</h2><a href="#path">View your path ↗︎</a></div><div class="card next-card"><span class="badge">WEEK ${String(next.week).padStart(2,'0')} · SESSION ${next.session}</span><h3>${esc(next.title)}</h3><p>${next.id===1?'A familiar place to start. Write a tiny Python function, test it, and explain it in your own words.':esc(next.task)}</p><div class="meta-row"><span>◷︎ &nbsp;45–60 min</span><span>⌘ &nbsp;${next.phase}</span><span>◇ &nbsp;${next.checkpoint?'Checkpoint':'Hands-on practice'}</span></div><div class="card-bottom"><div class="mini-steps"><span>01 Learn</span> &nbsp;→&nbsp; 02 Build &nbsp;→&nbsp; 03 Explain</div><a href="#lesson/${next.id}" class="btn">${state.drafts[next.id]?'Resume session':'Start session'} <span>→</span></a></div></div><section class="path-preview"><div class="section-title"><h2>The road ahead</h2><a href="#path">All ${weeks.length} weeks ↗︎</a></div><div class="card" style="padding:0 20px">${weeks.slice(Math.min(next.week-1,weeks.length-3),Math.min(next.week-1,weeks.length-3)+3).map((w,i)=>{const num=Math.min(next.week-1,weeks.length-3)+i+1;return `<a href="#path/week-${num}" class="path-row"><span class="path-number">${String(num).padStart(2,'0')}</span><div><strong>${esc(w.title)}</strong><p>${esc(w.subtitle)}</p></div><span class="row-right">${num===next.week?'You’re here':w.phase} &nbsp;→</span></a>`;}).join('')}</div></section></div><div class="dashboard-right"><section><div class="section-title"><h2>A rhythm you can keep</h2></div><div class="card rhythm-card"><div class="rhythm-header"><span>THIS WEEK</span><strong>${events.length}<small> / 4 sessions</small></strong></div><div class="day-grid">${['M','T','W','T','F','S','S'].map((day,i)=>{const hit=events.some(e=>((new Date(e.at).getDay()+6)%7)===i);return `<div class="day">${day}<i class="${hit?'done':''}">${hit?'✓︎':'·'}</i></div>`;}).join('')}</div><p>Four sessions, on your schedule.<br>Miss a day? Just pick up where you left off.</p></div></section><section class="note-card"><span class="eyebrow">A DIFFERENT WAY TO LEARN</span><h3>Hints are a ladder.<br>Not a shortcut.</h3><p>Try first. Get a small nudge when you need it. Rebuild later to make the skill your own.</p><a href="#review">How skill review works ↗︎</a></section></div></div>`;}
const projects=[{title:'Tiny dungeon engine',icon:'game',id:16,week:4,desc:'Build the core of a grid-based game. Turn commands into movement, then add a world of your own.',checks:['Movement engine passes its checks','Add walls, treasure, and a replay loop in VS Code','Write a README and three extra tests']},{title:'Playtime report',icon:'chart',id:24,week:6,desc:'Turn a small game-session dataset into a useful report with totals and a CSV export.',checks:['Aggregation function passes its checks','Read a local JSON file and export CSV','Handle invalid records and document the format']},{title:'Game-library organizer',icon:'library',id:44,week:11,desc:'Combine your automation skills into a tool that imports, cleans, searches, and exports your game library.',checks:['Complete weeks 6–11 core functions','Connect them into a working CLI in VS Code','Ship sample data, tests, and setup instructions']},{title:'Your independent build',icon:'code',id:48,week:12,desc:'Choose a small problem you care about. Define what done means, build a working version, and explain your choices.',checks:['Write inputs, outputs, and acceptance examples','Implement and debug without generated solutions','Publish a README and demonstrate the working program']}];
function renderProjectsOriginal(){return `${header('The project workshop','Small enough to finish. Real enough to be proud of.')}<p class="page-subtitle">Each milestone starts with a testable core in Forge. The full project takes shape in VS Code, where you connect the pieces, handle files, and ship something useful. Check off these milestones yourself as you finish them.</p><div class="project-grid">${projects.map((p,i)=>`<section class="card project-card"><div class="project-art" aria-hidden="true">${icon(p.icon)}</div><span class="badge">${i===3?'WEEK 12 · CAPSTONE':`WEEK ${p.week} · PROJECT ${i+1}`}</span><h3>${p.title}</h3><p>${p.desc}</p><div class="checklist">${p.checks.map((c,j)=>`<label><input type="checkbox" data-project="${i}-${j}" ${state.projectChecks[`${i}-${j}`]?'checked':''}>${c}</label>`).join('')}</div><div class="button-row" style="margin-top:20px"><a class="btn" href="#lesson/${p.id}">Open core challenge →</a><button class="btn light" data-action="project-brief" data-project-id="${i}">Download brief</button></div></section>`).join('')}</div>`;}
function renderReview(){const due=dueLessons(),finished=lessons.filter(l=>state.completed[l.id]);return `${header('Make it stick','Come back to a skill. Start from a blank page. See what you remember.')}<div class="path-intro"><strong>${due.length} ready</strong><p>Reviews are scheduled 1, 3, 7, then 14 days after successful attempts. A review starts with a fresh editor. Try without hints; if you need help, we’ll revisit it tomorrow. Repeated tasks are recall practice, not proof of general mastery.</p></div>${due.length?due.map(reviewRow).join(''):`<div class="card empty-state"><span style="font-size:30px;color:#8ca773">↻︎</span><h3>${finished.length?'You’re up to date.':'Your first review starts with a small win.'}</h3><p>${finished.length?'Nothing is due today. You can still revisit a completed session below.':'Complete a session and it will appear here when it is time to revisit it. Your notes and previous attempts stay saved.'}</p><a class="btn" href="#lesson/${nextLesson().id}">Continue learning →</a></div>`}${finished.length?`<div class="section-title" style="margin-top:27px"><h2>Revisit any completed skill</h2><span class="muted" style="font-size:10px">${finished.length} sessions</span></div>${finished.filter(l=>!due.includes(l)).map(reviewRow).join('')}`:''}`;}
function reviewRow(l){const c=state.completed[l.id],due=state.reviews[l.id]?.due||c.due;return `<div class="card review-row"><div><span class="badge">${c.assisted?'GUIDED PRACTICE':'INDEPENDENT COMPLETION'}</span><h3 style="margin-top:8px">${esc(l.title)}</h3><p>Week ${l.week} · ${due<=Date.now()?'Ready to revisit':'Next review '+new Date(due).toLocaleDateString()} · Start fresh and explain your solution.</p></div><a class="btn light" href="#lesson/${l.id}/review">Try from scratch ↗︎</a></div>`;}
function renderJournal(){const entries=lessons.filter(l=>state.explanations[l.id]||state.notes[l.id]);return `${header('Your notebook','A record of what you built, what broke, and what you figured out.')}<div class="notebook-layout"><div class="card notebook-card"><h3>A place to think</h3><p class="muted" style="font-size:11px;margin-top:6px">Plan a solution. Trace an input. Write down the bug before you fix it.</p><textarea id="scratch" class="form-input" placeholder="What am I trying to build?\nWhat are the inputs and outputs?\nWhat is the smallest example?">${esc(state.scratch)}</textarea><small class="muted" style="font-size:10px">Saved automatically in this browser.</small><details class="reference"><summary>Python pocket reference</summary><pre>${esc('def total(values):\n    result = 0\n    for value in values:\n        result += value\n    return result\n\n# Collections\nitems.append(value)\ncounts[key] = counts.get(key, 0) + 1\nseen = set()\nordered = sorted(items, key=lambda x: x["score"])\n\n# Strings and errors\ntext.strip().lower()\ntry:\n    value = int(text)\nexcept ValueError:\n    value = None\n\n# Debugging questions\n# What did I expect? What happened?\n# What is the smallest failing input?\n# Does the boundary case work?')}</pre></details><a href="#settings" class="btn light small" style="margin-top:18px">Back up your work →</a></div><div><div class="section-title"><h2>Your learning log</h2><button class="btn light small" data-action="export-notes">Export notes</button></div><div class="card notebook-card">${entries.length?entries.slice().reverse().map(l=>`<article class="journal-entry"><a href="#lesson/${l.id}"><h4>${esc(l.title)} ↗︎</h4></a><small>WEEK ${l.week} · ${state.completed[l.id]?(state.completed[l.id].assisted?'Guided practice':'Independent completion'):'In progress'}</small>${state.explanations[l.id]?`<p>${esc(state.explanations[l.id])}</p>`:''}${state.notes[l.id]?`<p><strong>Notes:</strong> ${esc(state.notes[l.id])}</p>`:''}</article>`).join(''):'<p class="muted" style="font-size:12px">Your explanations and session notes will appear here. Start with one small win.</p>'}</div></div></div>`;}
function renderSafetyNet(){const snapshots=readSnapshots().reverse(),recovered=recoveryKeys().concat(saveBlocked?[KEY]:[]);return `<div class="card settings-card"><h3>Automatic snapshots</h3><p>Forge keeps your last ${SNAPSHOT_LIMIT} snapshots in this browser, at most one every 6 hours. They undo mistakes and damaged saves. They live in the same browser storage as your progress, so they do not replace exported backups.</p>${snapshots.length?`<ul class="snapshot-list">${snapshots.map(s=>`<li><span><strong>${esc(new Date(s.at).toLocaleString())}</strong><small>${Object.keys(s.state.completed||{}).length} completed · ${Object.keys(s.state.drafts||{}).length} drafts</small></span><button class="btn light small" data-safety="restore-snapshot" data-snapshot="${s.at}">Restore</button></li>`).join('')}</ul>`:'<p style="margin-bottom:0">No snapshots yet. The first one is saved once you have some progress.</p>'}</div>${recovered.length?`<div class="card settings-card"><h3>Damaged data kept for recovery</h3><p>Forge could not read these saved records, so it kept them unchanged. Download one to keep it safe or to ask for help repairing it.</p><ul class="snapshot-list">${recovered.map(key=>{const at=Number(key.slice(RECOVERY_PREFIX.length));return `<li><span><strong>${esc(Number.isFinite(at)&&at?new Date(at).toLocaleString():'Current saved record')}</strong></span><div class="button-row"><button class="btn light small" data-safety="download-recovery" data-recovery-key="${esc(key)}">Download</button>${key===KEY?'':`<button class="btn light small" data-safety="delete-recovery" data-recovery-key="${esc(key)}">Delete</button>`}</div></li>`;}).join('')}</ul></div>`:''}`;}
function renderSettings(){return `${header('Make this your workspace','A comfortable pace, with your work under your control.')}<div class="card settings-card"><h3>Your practice rhythm</h3><p>Four sessions a week, whenever they fit. The timer is optional; finishing a task matters more than filling time.</p><label for="timer-minutes" style="font-size:12px">Session timer &nbsp;</label><select id="timer-minutes" class="form-input" style="width:auto"><option value="45" ${state.timerMinutes===45?'selected':''}>45 minutes</option><option value="60" ${state.timerMinutes===60?'selected':''}>60 minutes</option><option value="25" ${state.timerMinutes===25?'selected':''}>25 minutes · lighter day</option></select></div><div class="card settings-card"><h3>Your progress, backed up</h3><p>Progress, code, and notes are saved in this browser on this device. They do not sync automatically. Export a backup before switching devices or clearing browser data; import it here to continue. Import replaces this browser’s progress after confirmation.</p><div class="button-row"><button class="btn" data-action="export">Export backup ↓</button><button class="btn light" data-action="import">Import backup ↑</button><input type="file" id="import-file" accept=".json,application/json" hidden></div><p id="last-backup" style="margin-bottom:0">${esc(lastBackupText())}</p><p id="backup-message" aria-live="polite" style="margin-bottom:0"></p></div>${renderSafetyNet()}<div class="card settings-card"><h3>How to use Forge</h3><p>Attempt each problem before opening a hint. Run the checks, inspect failures, then explain your approach. Completions record whether you used hints or a reference solution. Reviews start fresh; self-report outside help honestly. You can skip basics from the learning path if you already know them.</p><p>Python runs locally in a browser worker, with an 8-second limit per execution after the engine loads. The first run downloads the bundled Python engine and may take a moment. Use return for challenge answers and print for your own debugging. Interactive input() and desktop graphics are not supported here. Download your code for full projects in VS Code.</p><p>The 24-week path builds foundations and habits. Confidence comes from independent practice on unfamiliar tasks and finished projects; completing the path is a starting point for that work.</p></div><a href="#home" class="btn light mobile-only">Back to workspace</a>`;}
function renderLesson(l,isReview){const code=isReview?l.starter:(state.drafts[l.id]??l.starter);current={...l,isReview,assisted:isReview?false:!!state.assisted[l.id],hints:isReview?0:(state.hints[l.id]||0),code};passedCode=null;lastRun=null;rating=null;elapsed=0;return `<div class="learn-header"><a class="back" href="${isReview?'#review':l.track?'#quests/'+l.chapter:'#path/week-'+l.week}">← ${isReview?'Skill review':l.track?'Quest book':'Learning path'}</a><div class="timer"><span>◷︎</span><strong id="timer-label">${state.timerMinutes}:00</strong><button data-action="timer" id="timer-toggle">Start focus timer</button><button data-action="timer-reset" aria-label="Reset focus timer">↻︎</button></div></div>${courseLessonBanner(l,isReview)}<div class="lesson-title"><span class="badge ${l.checkpoint||l.track?'orange':''}">${l.track?esc(l.phase.toUpperCase())+' · QUEST '+l.session:'WEEK '+String(l.week).padStart(2,'0')+' · SESSION '+l.session} ${isReview?'· REVIEW':''}</span><h1>${esc(l.title)}</h1><p>${isReview?'Rebuild from memory. Your original code is saved; this review uses a separate fresh attempt.':l.checkpoint?'Plan first. Build from the specification. Explain why your solution works.':'Trace the example. Make a plan. Write your own solution.'}</p></div><div class="learning-layout"><section class="card lesson-copy"><h3>${isReview?'Recall before you reveal':'A small idea to build on'}</h3>${isReview?`<p>Try the task from memory before revealing the refresher. It’s fine to need help; we’ll schedule another review.</p><button class="btn light small" data-q="refresher" style="margin-top:12px">Reveal refresher · counts as help</button><div id="refresher" hidden><p>${esc(l.concept)}</p>${l.example?`<pre>${esc(l.example)}</pre>`:''}</div>`:`<p>${esc(l.concept)}</p>${l.example?`<pre>${esc(l.example)}</pre>`:''}`}${lessonLearning(l,isReview)}<div class="task"><h3>Your challenge</h3><p>${esc(l.task)}</p><div class="io-example">${l.sqlPreview?esc(l.sqlPreview).replaceAll('\n','<br>'):l.cases.slice(0,2).map(c=>`${esc(l.name)}(${esc(c.args.map(pyrepr).join(', '))})<br>→ ${esc(pyrepr(c.expected))}`).join('<br><br>')}</div></div><div class="hint-box" id="hint-box"></div><div class="help-ladder" id="help-ladder"></div><p style="font-size:10px;margin-top:10px" id="assistance-status">${current.assisted?'This attempt uses guidance. Revisit later from scratch.':'Try for 5–10 minutes before reaching for a hint.'}</p><details class="reference"><summary>Session notes & plan</summary><textarea id="session-note" class="form-input" rows="5" placeholder="Inputs → outputs\nMy plan\nSmallest failing example">${esc(state.notes[l.id]||'')}</textarea></details><div class="extend"><strong>Take it further ↗︎</strong><br>${esc(l.extension)}</div></section><div class="editor-column"><section class="editor-panel"><div class="editor-toolbar"><span class="file-name">◉ &nbsp; ${esc(l.file||l.name+'.py')}</span><div><button data-action="download-code">↓ Download</button><button data-action="reset-code">Reset code</button></div></div><div class="editor-wrap"><div class="line-numbers" id="line-numbers" aria-hidden="true"></div><textarea id="editor" aria-label="Python code editor" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off">${esc(code)}</textarea></div><div class="editor-actions"><small id="editor-saved">${isReview?'Fresh review attempt':'Changes saved automatically'}</small><div><button class="btn small" data-action="stop" id="stop-btn" hidden>Stop</button><button class="btn" data-action="run" id="run-btn">▶︎ &nbsp; Run checks</button></div></div></section><section class="card console"><div class="console-heading"><strong>OUTPUT & CHECKS</strong><span class="badge" id="run-status">READY WHEN YOU ARE</span></div>${typeof predictionPanel==='function'?predictionPanel(l):''}<div id="test-results"></div><pre id="output">Your code runs in real Python.\nWrite a solution, then run the checks.\nTip: Ctrl/⌘ + Enter runs your code.</pre></section><section class="card completion"><h3>Make the win yours.</h3><p>Pass the checks, then explain the approach in your own words. What would happen on an empty input or a boundary value?</p><label for="explanation">My approach, and one edge case</label><textarea id="explanation" placeholder="I start by… This works because… One edge case is…">${esc(isReview?'':state.explanations[l.id]||'')}</textarea><label>How independently could you do this again?</label><div class="rating-group"><button data-rating="1">Need another try</button><button data-rating="2">With a nudge</button><button data-rating="3">On my own</button></div><label style="margin-bottom:15px"><input type="checkbox" id="outside-help"> I used outside help (AI, someone else, or code from the web). Honest answer: 0 XP and a redo bounty.</label><button class="btn" data-action="complete" id="complete-btn">Save session & continue →</button><p id="completion-message" role="status" style="margin-top:10px">Run checks on your current code before completing.</p></section></div></div>`;}
function syncLines(){if($('#editor'))$('#line-numbers').textContent=Array.from({length:$('#editor').value.split('\n').length},(_,i)=>i+1).join('\n');}
function stopRun(message){if(worker){worker.terminate();worker=null;}clearTimeout(runTimeout);if($('#run-btn')){$('#run-btn').disabled=false;$('#run-btn').textContent='▶︎  Run checks';$('#stop-btn').hidden=true;}if(message&&$('#output')){$('#output').textContent=message;$('#run-status').textContent='STOPPED';}}
function markAssisted(){current.assisted=true;if(!current.isReview){state.assisted[current.id]=true;state.hints[current.id]=current.hints;save();}if($('#outside-help'))$('#outside-help').checked=true;$('#assistance-status').textContent='This attempt uses guidance. Revisit later from scratch.';}
function renderHints(){const lesson=lessons[current.id-1];$('#hint-box').innerHTML=lesson.hints.slice(0,Math.min(current.hints,2)).map((h,i)=>`<p><strong>Hint ${i+1}.</strong> ${esc(h)}</p>`).join('');$('#hint-btn').textContent=current.hints>=2?'Hints revealed':'A small hint';}
async function run(){if(!current||$('#run-btn').disabled)return;const l=current,code=$('#editor').value,prediction=typeof questSnapshot==='function'?questSnapshot():null;passedCode=null;$('#test-results').innerHTML='';$('#output').textContent='Loading Python… First load can take a moment.';$('#run-status').textContent='STARTING PYTHON';$('#run-btn').disabled=true;$('#run-btn').textContent='Running…';$('#stop-btn').hidden=false;worker=new Worker('runner.js?v='+FORGE_VERSION);runTimeout=setTimeout(()=>{stopRun('Python took too long to load. Check your connection and try again.');},90000);worker.onmessage=({data})=>{if(data.type==='ready'){clearTimeout(runTimeout);$('#run-status').textContent='RUNNING';$('#output').textContent='Checking your function…';runTimeout=setTimeout(()=>stopRun('Stopped after 8 seconds. Check for a loop that never ends, or reduce the amount of work.'),8000);return;}if(data.type==='error'){stopRun('Could not start Python. Please try again.\n'+data.message);return;}if(data.type==='result'){stopRun();const result=data.data;lastRun=result;$('#test-results').innerHTML=result.results.map((r,i)=>`<div class="test-row ${r.ok?'pass':'fail'}">${r.ok?'✓︎':'×'} Check ${i+1} ${r.ok?'passed':r.mutated&&l.noMutation?'failed: the input was changed, but this task requires it to stay unchanged.':r.error?'<br>'+esc(l.sql?r.error.trim().split('\n').pop().replace(/^sqlite3\.\w+Error: /,'SQL error: '):r.error):`<br>${l.sql?(i?'Dataset: second, hidden data':'Dataset: practice data'):'Input: '+esc(r.args)}<br>Expected: ${esc(r.expected)}<br>Received: ${esc(r.actual)}`}</div>`).join('');const ok=!result.error&&result.results.length===l.cases.length&&result.results.every(r=>r.ok);if(ok&&$('#editor').value===code)passedCode=code;$('#run-status').textContent=ok?'ALL CHECKS PASSED':'LET’S DEBUG';$('#output').textContent=(result.error||'')+(result.stdout?'\nYour output:\n'+result.stdout:'')+(ok?'\nAll checks passed. Explain your approach below.':!result.error?'\nTrace the smallest failing example and try again.':'\nRead the last line of the error first.');$('#completion-message').textContent=ok?'Checks passed. Add an explanation and choose your independence level.':'Keep going. Complete the session after the current code passes.';if(typeof questAfterRun==='function')questAfterRun(result,ok,code,prediction);}};worker.onerror=e=>stopRun('Python could not run. Please retry. '+e.message);worker.postMessage({code:l.sql&&typeof sqlWrap==='function'?sqlWrap(l,code):code,cases:l.cases,name:l.name,packages:l.packages||[],checkMutation:!!l.noMutation,requirements:l.requirements||[]});}
function complete(){const explanation=$('#explanation').value.trim(),code=$('#editor').value;if(passedCode!==code)return toast('Run the checks on your current code and pass them first.');if(explanation.length<30)return toast('Add an explanation of at least 30 characters, including an edge case.');if(!rating)return toast('Choose how independently you could do this again.');const helped=current.assisted||$('#outside-help').checked||rating<3;const reward=typeof questOnComplete==='function'?questOnComplete(helped):'';const previous=state.completed[current.id],review=state.reviews[current.id],stage=helped?0:Math.min(3,(review?.stage??-1)+1);const due=Date.now()+[1,3,7,14][stage]*86400000;state.explanations[current.id]=explanation;state.ratings[current.id]=rating;state.reviews[current.id]={stage,due};state.completed[current.id]={at:Date.now(),assisted:previous?(previous.assisted && helped):helped,due,confidence:rating};if(!current.isReview)state.drafts[current.id]=code;if(!previous||current.isReview)state.events.push({id:current.id,at:Date.now(),review:current.isReview,assisted:helped});save();toast(reward||(helped?'Practice saved. Revisit this skill tomorrow.':'Independent completion saved. Nice work.'));location.hash=(typeof questReturnHash==='function'&&questReturnHash())||(current.isReview?'#review':nextHashAfter(current));}
function tick(){const remain=Math.max(0,state.timerMinutes*60-elapsed);if($('#timer-label'))$('#timer-label').textContent=`${Math.floor(Math.ceil(remain)/60)}:${String(Math.ceil(remain)%60).padStart(2,'0')}`;if(remain===0){pauseTimer();toast('Focus session complete. Take a break or finish your thought.');}}
let lastTick=0;
function pauseTimer(){clearInterval(clock);clock=null;timerRunning=false;if($('#timer-toggle'))$('#timer-toggle').textContent='Resume timer';}
function route(){stopRun();pauseTimer();const [page='home',id,mode]=location.hash.slice(1).split('/');const main=$('#main');if(!lessons.length)return;current=null;if(page==='lesson'){const l=lessons.find(x=>x.id===Number(id));if(!l){location.hash='#path';return;}main.innerHTML=renderLesson(l,mode==='review');syncLines();renderHints();}else{const renders={home:renderHome,path:renderPath,projects:renderProjects,review:renderReview,journal:renderJournal,settings:renderSettings,guide:renderGuide,resources:renderResources,readiness:renderReadiness,unit:()=>renderUnit(Number(id)||1),quests:()=>typeof renderQuests==='function'?renderQuests(id):renderPath()};main.innerHTML=(renders[page]||renderHome)();}updateNav(["unit","guide","resources"].includes(page)?"path":page==="readiness"?"projects":page);if(["unit","guide","resources","readiness"].includes(page))$("#breadcrumb").textContent=({unit:"Weekly handbook",guide:"Start here",resources:"Source library",readiness:"Readiness evidence"})[page];window.scrollTo(0,0);if(typeof questMounted==='function')questMounted(page,id,mode);}
document.addEventListener('input',e=>{if(e.target.id==='editor'){current.code=e.target.value;if(!current.isReview){state.drafts[current.id]=current.code;save();}passedCode=null;$('#completion-message').textContent='Code changed. Run the checks again before completing.';syncLines();}if(e.target.id==='explanation'&&!current.isReview){state.explanations[current.id]=e.target.value;save();}if(e.target.id==='scratch'){state.scratch=e.target.value;save();}if(e.target.id==='session-note'){state.notes[current.id]=e.target.value;save();}});
document.addEventListener('change',e=>{if(e.target.dataset.project){state.projectChecks[e.target.dataset.project]=e.target.checked;save();}if(e.target.id==='timer-minutes'){state.timerMinutes=Number(e.target.value);save();toast('Timer preference saved.');}if(e.target.id==='import-file')importBackup(e.target.files[0]);});
document.addEventListener('keydown',e=>{if(e.target.id==='editor'){if(e.key==='Tab'){e.preventDefault();e.target.setRangeText('    ',e.target.selectionStart,e.target.selectionEnd,'end');e.target.dispatchEvent(new Event('input',{bubbles:true}));}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();run();}}});
document.addEventListener('click',e=>{const r=e.target.closest('[data-rating]');if(r){rating=Number(r.dataset.rating);document.querySelectorAll('[data-rating]').forEach(b=>b.classList.toggle('selected',b===r));}const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(action==='run')run();if(action==='stop')stopRun('Stopped. You can edit your code and try again.');if(action==='hint'){current.hints=Math.min(2,current.hints+1);markAssisted();renderHints();}if(action==='refresher'){$('#refresher').hidden=false;markAssisted();el.hidden=true;}if(action==='solution'){if(!confirm('Reveal the reference solution? This attempt will count as guided practice. Your draft will be replaced; download it first if you want to keep it.'))return;markAssisted();$('#editor').value=lessons[current.id-1].solution;$('#editor').dispatchEvent(new Event('input',{bubbles:true}));toast('Trace each line. Revisit from scratch later to test recall.');}if(action==='reset-code'){if(!confirm('Replace the code in this editor with the starter? Your notes will be kept.'))return;$('#editor').value=current.starter;$('#editor').dispatchEvent(new Event('input',{bubbles:true}));}if(action==='download-code')download(current.file||current.name+'.py',$('#editor').value);if(action==='complete')complete();if(action==='timer'){if(timerRunning)pauseTimer();else{timerRunning=true;lastTick=Date.now();$('#timer-toggle').textContent='Pause';clock=setInterval(()=>{const now=Date.now();elapsed+=(now-lastTick)/1000;lastTick=now;tick();},1000);}}if(action==='timer-reset'){pauseTimer();elapsed=0;tick();$('#timer-toggle').textContent='Start focus timer';}if(action==='export')exportBackup();if(action==='import')$('#import-file').click();if(action==='export-notes')download('forge-notebook.md','# My Forge notebook\n\n'+state.scratch+'\n\n'+lessons.filter(l=>state.notes[l.id]||state.explanations[l.id]).map(l=>'## '+l.title+'\n\n'+(state.explanations[l.id]||'')+'\n\n'+(state.notes[l.id]||'')).join('\n\n'));if(action==='project-brief'){const p=projects[Number(el.dataset.projectId)];download(p.title.toLowerCase().replaceAll(' ','-')+'.md',`# ${p.title}\n\n${p.desc}\n\n## Definition of done\n${p.checks.map(c=>'- [ ] '+c).join('\n')}\n\n## Build in VS Code\n1. Create a project folder and a README.\n2. Download your challenge function from Forge as core.py.\n3. Create main.py for the CLI and test_core.py for tests.\n4. Keep file access and input() in main.py; keep core.py pure.\n5. Write an ordinary case, an empty case, and a boundary case using unittest.\n6. Run: python -m unittest\n7. Run: python main.py\n8. Document setup, sample input, expected output, and limitations.\n\n## Next extension\n${lessons[p.id-1].extension}\n`);}});
async function importBackup(file){if(!file)return;try{if(file.size>10*1024*1024)throw Error('Backup is too large.');const obj=JSON.parse(await file.text());if(obj.version!==1)throw Error('This is not a supported Forge backup.');const clean=emptyState(),stringMaps=['drafts','notes','explanations'];for(const key of stringMaps){if(!obj[key]||typeof obj[key]!=='object'||Array.isArray(obj[key]))throw Error('Invalid '+key);for(const [id,value] of Object.entries(obj[key])){if(!validLessonKey(id)||typeof value!=='string'||value.length>200000)throw Error('Invalid '+key+' entry');clean[key][id]=value;}}for(const key of ['completed','reviews','assisted','hints','ratings','projectChecks']){if(!obj[key]||typeof obj[key]!=='object'||Array.isArray(obj[key]))throw Error('Invalid '+key);for(const [id,v] of Object.entries(obj[key])){if(key==='projectChecks'){if(!/^[0-3]-[0-2]$/.test(id)||typeof v!=='boolean')throw Error('Invalid project checkpoint');}else{if(!validLessonKey(id))throw Error('Invalid lesson ID');if(key==='completed'&&(!v||!Number.isFinite(v.at)||!Number.isFinite(v.due)||typeof v.assisted!=='boolean'))throw Error('Invalid completion');if(key==='reviews'&&(!v||!Number.isFinite(v.due)||!Number.isInteger(v.stage)||v.stage<0||v.stage>3))throw Error('Invalid review');if(key==='assisted'&&typeof v!=='boolean')throw Error('Invalid assistance');if(key==='hints'&&(!Number.isInteger(v)||v<0||v>2))throw Error('Invalid hint count');if(key==='ratings'&&![1,2,3].includes(v))throw Error('Invalid rating');}clean[key][id]=v;}}if(!Array.isArray(obj.events)||obj.events.some(e=>!e||!Number.isInteger(e.id)||e.id<1||e.id>lessons.length||!Number.isFinite(e.at)))throw Error('Invalid session history');clean.events=obj.events.map(e=>({id:e.id,at:e.at,review:!!e.review,assisted:!!e.assisted}));for(const key of ['labChecks','labNotes','evidence']){const map=obj[key]||{};if(typeof map!=='object'||Array.isArray(map))throw Error('Invalid '+key);for(const [id,value] of Object.entries(map)){const allowed=key==='labChecks'?/^([1-9]|1[0-9]|2[0-4])-([0-9]+)$/.test(id):key==='labNotes'?/^(0?[1-9]|1[0-9]|2[0-4])$/.test(id):/^skill-[0-9]+$/.test(id);if(!allowed||(key==='labChecks'?typeof value!=='boolean':typeof value!=='string'))throw Error('Invalid '+key+' entry');clean[key][id]=value;}}if(typeof obj.scratch!=='string')throw Error('Invalid notebook');clean.scratch=obj.scratch;clean.timerMinutes=[25,45,60].includes(obj.timerMinutes)?obj.timerMinutes:45;if(typeof sanitizeGame==='function')clean.game=sanitizeGame(obj.game);if(!confirm('Replace this browser’s current Forge progress with this backup? Forge keeps a snapshot of your current progress first, so you can undo this from settings.'))return;takeSnapshot(true);saveBlocked=false;progressUnreadable=false;clearNotice('recovery');clearNotice('stale');state=clean;save();route();toast('Backup restored. Your workspace is ready.');}catch(error){toast('Could not import: '+error.message);$('#import-file').value='';}}
window.addEventListener('hashchange',route);
lastSnapshotAt=readSnapshots().reduce((latest,s)=>Math.max(latest,s.at),0);showRecoveryNotice();signalTabs('ping');
Promise.all([fetch('curriculum.json?v='+FORGE_VERSION),fetch('handbook.json?v='+FORGE_VERSION)].map(async pending=>{const response=await pending;if(!response.ok)throw Error('Course content unavailable');return response.json();})).then(([data,book])=>{curriculum=data;handbook=book;lessons=data.lessons;weeks=data.weeks;takeSnapshot();route();checkBackupReminder();}).catch(e=>{$('#main').innerHTML='<div class="card empty-state"><h1>Let’s reconnect.</h1><p>The learning path could not load. Refresh the page to try again.</p><button class="btn" onclick="location.reload()">Try again</button></div>';});

/* Course edition 2: teaching, local practice, and evidence beyond function checks. */
function validLessonKey(id){return /^\d+$/.test(id)&&lessons.some(l=>l.id===Number(id));}
function sourceLinks(keys){return keys.map(key=>{const s=handbook.sources[key];return `<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer"><strong>${esc(s.title)} <span aria-hidden="true">↗︎</span></strong><small>${esc(s.purpose)}</small></a>`;}).join('');}
function courseToolbar(){return `<div class="course-toolbar"><a href="#guide" class="btn light">Start here</a><a href="#resources" class="btn light">Sources & coverage</a><a href="#readiness" class="btn light">Readiness evidence</a></div>`;}
function renderHome(){let result=renderHomeOriginal();const marker='<section class="hero">';result=result.replace(marker,`<div class="course-welcome"><div><span class="badge">EXPANDED LEARNING PATH</span><strong>96 sessions · 24 weekly handbooks · 24 local labs</strong><p>Python foundations, practical development tools, databases, APIs, and independent projects.</p></div><a class="btn light" href="#guide">Start here →</a></div><div class="course-welcome"><div><span class="badge">SIDE QUESTLINES</span><strong>${lessons.filter(l=>l.track).length} extra quests, alongside the core path</strong><p>Practice drills, bug hunts, SQL, interview problems, and hardware labs.</p></div><a class="btn light" href="#quests">Open quest book →</a></div>${marker}`);return result;}
function renderPath(){const focused=Number(location.hash.split('week-')[1])||nextLesson().week;return `${header('A path toward independent work','Learn the idea. Write the code. Debug it. Ship something you can explain.')}${courseToolbar()}<div class="path-intro"><div><strong>24 weeks</strong><span class="muted">4 sessions a week · a flexible pace</span></div><p>Weeks 1–12 rebuild Python foundations through games and automation. Weeks 13–24 add developer tools, tests, SQL, HTTP, maintainable services, collaboration, and a practical handoff. Each week includes a handbook and a local lab. Your original lesson progress stays attached to the same lessons.</p></div><div class="course-notice"><strong>What completion means</strong><p>Browser checks verify small pieces of behavior. Local labs and evidence notes show whether you can put those pieces together. The readiness rubric is a personal assessment, not a certificate or a prediction of a job offer.</p></div>${weeks.map((w,i)=>{const u=handbook.units[i],week=i+1;return `${week===1||week===13?`<div class="stage-heading"><span class="eyebrow">STAGE ${week===1?'01':'02'}</span><h2>${week===1?'Python foundations':'Engineering and entry-level practice'}</h2><p>${week===1?'Build a working mental model, then use it in small complete projects.':'Practice the tools, boundaries, and handoffs that surround real code.'}</p></div>`:''}<details class="card week-card" id="week-${week}" ${week===focused?'open':''}><summary><span class="path-number">${String(week).padStart(2,'0')}</span><div><span class="eyebrow muted">${esc(w.phase)}</span><h3>${esc(w.title)}</h3><p>${esc(w.subtitle)}</p></div><span class="week-count">${progressForWeek(week)} / 4 &nbsp;⌄</span></summary><div class="unit-preview"><p><strong>Before the challenges:</strong> ${esc(u.goals[0])}</p><div class="button-row"><a class="btn light" href="#unit/${week}">Read handbook & local lab →</a><a class="btn light" href="labs/week-${String(week).padStart(2,'0')}.zip" download>Download lab kit ↓</a></div></div><div class="lesson-grid">${lessons.filter(l=>isCore(l)&&l.week===week).map(l=>`<a class="lesson-link" href="#lesson/${l.id}"><span class="lesson-state">${state.completed[l.id]?'✓︎':'○'}</span><div>${l.session}. ${esc(l.title)}<small>${l.checkpoint?'Apply & explain':'Learn · practice · explain'}${state.completed[l.id]?' · '+(state.completed[l.id].assisted?'Guided':'Independent'):''}</small></div></a>`).join('')}</div><div class="week-lab-summary"><strong>Local lab: ${esc(u.lab.title)}</strong><p>${u.lab.acceptance.length} acceptance criteria · ${u.lab.steps.length} build steps · ${u.lab.acceptance.filter((_,j)=>state.labChecks[`${week}-${j}`]).length} criteria self-checked</p></div></details>`;}).join('')}`;}
function courseLessonBanner(l,isReview){return `<div class="lesson-course-banner"><div><strong>${isReview?'Fresh recall attempt':'Week '+l.week+' · handbook and local practice'}</strong><p>${isReview?'Keep the handbook closed for this attempt; revealing teaching material counts as guidance.':'New to the concept? Read the handbook first, then return to this challenge.'}</p></div>${isReview?'':`<a class="btn light small" href="#unit/${l.week}">Open handbook →</a>`}</div>`;}
function workedBlock(u){return `<section class="worked-example"><span class="eyebrow">A SEPARATE WORKED EXAMPLE</span><pre>${esc(u.worked.code)}</pre><div class="button-row"><button class="btn light small" data-course-action="example" data-week="${u.week}">Run this example ▶︎</button><span class="muted">Predict its output before running.</span></div><pre class="example-output" id="example-output" aria-live="polite">Output appears here.</pre><details><summary>Trace the example and see expected output</summary><pre>${esc(u.worked.output)}</pre><ol>${u.worked.trace.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></details></section>`;}
function paras(text){return String(text||'').split('\n\n').map(p=>`<p>${esc(p).replaceAll('\n','<br>')}</p>`).join('');}
function teachingSections(u){const plain=u.plain?`<div class="plain-sections">${u.watch?`<a class="watch-first" href="${esc(u.watch.url)}" target="_blank" rel="noopener noreferrer"><span>▶ WATCH FIRST (FREE)</span><strong>${esc(u.watch.label)}</strong><small>Harvard's free lectures explain this week's ideas on video. Watch, then come back and read below.</small></a>`:''}${u.plain.map(s=>`<section class="plain"><h3>${esc(s.title)}</h3>${paras(s.text)}${s.code?`<pre>${esc(s.code)}</pre>`:''}</section>`).join('')}<h3 class="summary-heading">Quick reference summary</h3></div>`:'';return `<div class="teaching-sections">${plain}${u.sections.map(s=>`<section><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p></section>`).join('')}</div>`;}
function lessonLearning(l,isReview){const u=handbook.units[l.week-1];if(isReview)return '';return `<div class="lesson-objectives"><h3>What to practice</h3><ul>${l.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><details class="inline-handbook" ${l.session===1?'open':''}><summary>The full explanation · week ${l.week}</summary>${teachingSections(u)}<div class="inline-note">For a runnable worked example, mistakes to watch for, and the full local lab, <a href="#unit/${l.week}">open this week’s handbook →</a>.</div></details><details class="inline-handbook"><summary>References for this lesson</summary>${sourceLinks(l.resources)}</details>`;}
function renderUnit(number){const u=handbook.units.find(x=>x.week===number);if(!u)return `<div class="card empty-state"><h2>Choose a week from your path.</h2><a class="btn" href="#path">Open learning path</a></div>`;const first=lessons.find(l=>l.week===number);return `<a class="back" href="#path/week-${number}">← Learning path</a>${header(`Week ${number}: ${esc(u.title)}`,esc(u.phase)+' · Read, predict, practice, then build locally.')}<div class="unit-layout"><article class="card handbook-article"><span class="badge">ORIGINAL FORGE LESSON · SOURCES LINKED BELOW</span><h2>By the end of this week</h2><ul>${u.goals.map(g=>`<li>${esc(g)}</li>`).join('')}</ul><p class="prerequisite"><strong>Before you start:</strong> ${esc(u.prerequisites)}. If a term is unfamiliar, use the <a href="#guide">Start Here glossary</a> and revisit the prerequisite session.</p>${teachingSections(u)}${workedBlock(u)}<section class="mistake-panel"><h3>Common mistakes to catch</h3><ul>${u.mistakes.map(m=>`<li>${esc(m)}</li>`).join('')}</ul></section><section><h3>Explain before moving on</h3><ol>${u.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ol><p class="muted">Write your answers in your notebook. If you cannot explain a point yet, reread its section and trace the example with a different input.</p><a class="btn" href="#lesson/${first.id}">Start the week’s challenges →</a></section><section class="unit-sources"><h3>References and optional extra practice</h3><p>These external sources support the concepts. Forge’s explanations, examples, and challenges are written for this path; paid certificates and subscriptions are not required.</p>${sourceLinks(u.sources)}</section></article><aside class="card lab-panel"><span class="eyebrow">PUT IT TOGETHER · LOCAL LAB</span><h2>${esc(u.lab.title)}</h2><p>Use VS Code on your computer. Plan one small increment per session, then finish the lab before moving on. Allow an extra session when a project needs it.</p><a class="btn" href="labs/week-${String(number).padStart(2,'0')}.zip" download>Download starter lab kit ↓</a><p class="kit-note">Includes a README, checkpoint scaffold, standard-library tests, and sample cases. Tests start red until you implement the core; the full lab goes beyond these supplied checks.</p><h3>Build steps</h3><ol>${u.lab.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><h3>Acceptance criteria</h3><div class="checklist">${u.lab.acceptance.map((s,j)=>`<label><input type="checkbox" data-lab="${number}-${j}" ${state.labChecks[`${number}-${j}`]?'checked':''}>${esc(s)}</label>`).join('')}</div><h3>What to keep</h3><ul>${u.lab.deliverables.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><label for="lab-evidence">My evidence and remaining gaps</label><textarea class="form-input" id="lab-evidence" data-lab-notes="${number}" rows="7" placeholder="What I ran, expected/actual output, tests, a bug I fixed, help used, and what still needs work…">${esc(state.labNotes[number]||'')}</textarea><small>Saved in this browser. Checkboxes are self-reported; keep commands, outputs, or repository links as evidence.</small></aside></div>`;}
function renderProjects(){return `${renderProjectsOriginal()}<section class="local-labs"><div class="section-title"><h2>24 local labs for real practice</h2><a href="#readiness">Record readiness evidence →</a></div><p>These labs bridge a short checked function and a working program. Download the scaffold, build the full workflow, and verify the acceptance criteria yourself.</p><div class="lab-catalog">${handbook.units.map(u=>`<a class="card lab-tile" href="#unit/${u.week}"><span class="badge">WEEK ${u.week}</span><h3>${esc(u.lab.title)}</h3><p>${esc(u.goals[0])}</p><small>${u.lab.acceptance.filter((_,j)=>state.labChecks[`${u.week}-${j}`]).length} / ${u.lab.acceptance.length} criteria self-checked · Open brief →</small></a>`).join('')}</div></section>`;}
const readinessSkills=[
 ['Python fundamentals','Implement a small unfamiliar function from a written spec; explain values, control flow, collections, functions, mutation, and errors.','Weeks 1–5 and 12',12],
 ['Independent problem solving','Clarify a changed requirement, choose a data structure, solve examples, and explain time/space costs.','Weeks 8–9, 19, and 24',24],
 ['Debugging and tests','Reproduce a bug, add a test that fails on the buggy version, fix it, and run the suite.','Weeks 5, 14, and 22',14],
 ['Developer workflow','Create a clean environment, inspect diffs, make a focused branch/commit, and prepare a reviewable PR.','Start Here and weeks 13, 22–23',13],
 ['Files and automation','Build a CLI that validates data, previews changes, reports failures, and behaves predictably on reruns.','Weeks 6–7, 15, and 21',21],
 ['SQL','Write filtered queries, a grouped report, and a join; bind values and verify a transaction rollback.','Week 16',16],
 ['HTTP and service boundaries','Handle status/errors/timeouts and pagination; expose tested rules through a small local API.','Weeks 17 and 20',20],
 ['Maintainability','Read an existing feature path, preserve a contract, inject an I/O dependency, and document a change.','Weeks 10, 18, and 22',22],
 ['A shipped project','Demonstrate a complete workflow with sample data, tests, clean setup instructions, and an honest limitation.','Weeks 11 and 23',23],
 ['Interview and handoff communication','Explain a project tradeoff and bug fix, complete a small take-home change, and identify what remains uncertain.','Week 24',24]
];
function renderReadiness(){const recorded=readinessSkills.filter((_,i)=>(state.evidence[`skill-${i}`]||'').trim().length>=40).length;return `${header('Show yourself what you can do','Use working examples and independent attempts to decide what to practice next.')}${courseToolbar()}<div class="path-intro"><strong>${recorded} / ${readinessSkills.length}</strong><p>Areas with an evidence note of at least 40 characters. This counts recorded reflection, not verified mastery. Include a repository link, run command, output, test result, and help used. Revise the note when a new attempt exposes a gap.</p></div><div class="readiness-grid">${readinessSkills.map(([title,desc,weeks,week],i)=>`<section class="card readiness-card"><span class="badge">${esc(weeks)}</span><h2>${esc(title)}</h2><p>${esc(desc)}</p><label for="evidence-${i}">My evidence, help used, and next gap</label><textarea id="evidence-${i}" class="form-input" data-evidence="skill-${i}" rows="5" placeholder="I independently built/fixed… I verified it by… I used help with… Next I need to practice…">${esc(state.evidence[`skill-${i}`]||'')}</textarea><a class="btn light small" href="#unit/${week}">Revisit this practice →</a></section>`).join('')}</div><section class="card handbook-article" style="margin-top:20px"><h2>Choose your next specialization</h2><p>This path develops Python, automation, backend basics, and shared engineering habits. A particular role may need additional skills. Use a real job description to decide what to add: frontend roles need HTML/CSS/JavaScript and accessibility; data roles may need deeper SQL, statistics, and pandas; game programming may need C#/C++, engine workflows, and real-time systems. Infrastructure roles may need Linux, networking, and cloud operations. Build the fundamentals here, then add one relevant track rather than trying to learn every stack at once.</p><p>Start applying and discussing your projects while practicing. Use interview feedback and independent work to adjust this rubric; you do not need to feel finished learning before exploring entry-level roles.</p></section>`;}
function renderResources(){const groups=[['Beginner explanations',['w3','w3vars','w3func','cs50']],['Python language and standard library',['python','values','flow','collections','modules','files','errors','classes','regex','dates','paths','csv','containers','heap','dataclass','annotations']],['Developer tools and testing',['vscode','venv','mit','git','github','pytest','unittest','args','logging','ci']],['Databases and services',['w3sql','sql','http','requests','api']]];return `${header('Sources and curriculum coverage','A researched map with original lessons and direct references.')}${courseToolbar()}<section class="card handbook-article"><h2>How the content is used</h2><p>Forge combines a beginner-friendly sequence informed by W3Schools and CS50P, Python behavior checked against the official documentation, and practical tools supported by their maintainers’ documentation. The teaching, game examples, challenges, and lab specifications are original. External readings are optional explanations or references rather than copied course chapters.</p><p>Reviewed ${esc(handbook.edition)}. The bundled browser interpreter is Python 3.12; examples target compatible Python 3 behavior. External documentation can move to a newer release. Use the documentation version selector if a feature differs from your local interpreter. Newer optional features are not required by these exercises.</p><h3>Coverage and boundaries</h3><p>Included: values/types, operators, conditions, loops, strings, collections, functions/scope, mutation, modules, exceptions, files, JSON/CSV, basic OOP, iterators, regex, dates, testing, environments, Git, SQL, HTTP, small services, logging, core algorithm patterns, maintenance, and project delivery.</p><p>Not a complete computer-science degree or every role’s stack. Advanced metaprogramming, distributed systems, advanced async/concurrency, deep framework internals, and production-scale deployment are future specializations. The purpose is reliable beginner-to-entry-level Python practice and evidence of independent work.</p></section>${groups.map(([title,keys])=>`<section class="card handbook-article source-group"><h2>${title}</h2><div class="source-grid">${sourceLinks(keys)}</div></section>`).join('')}`;}
function renderGuide(){return `${header('Start here. Build a reliable foundation.','You can begin in the browser, then carry the same ideas into VS Code.')}${courseToolbar()}<div class="unit-layout"><article class="card handbook-article"><h2>1. Use a repeatable learning loop</h2><ol><li><strong>Recall, 5 minutes:</strong> explain yesterday’s idea without opening the answer.</li><li><strong>Learn, 10–15 minutes:</strong> read the weekly handbook, predict the example, and run it.</li><li><strong>Build, 20–25 minutes:</strong> attempt the session challenge. Write a plan and try before hints.</li><li><strong>Explain, 5–10 minutes:</strong> inspect a failure, add a new case, and describe why the solution works.</li><li><strong>Transfer:</strong> build the weekly local lab in small increments. Budget an extra session when needed; 24 weeks is a pace suggestion, not a deadline.</li></ol><p>After a guided solution, revisit from a blank editor. Documentation is useful for syntax; a complete generated answer should be treated as help, recorded honestly, and followed by a later independent attempt. You are building the ability to reason, debug, and adapt.</p><h2>2. Know what the browser does</h2><p>The editor runs real Python 3.12 in a worker. Define the exact requested function and return the requested value. Use print for debugging output. A run checks supplied cases, not every possible implementation property. Some tasks ask for a loop, class, or data structure: inspect that requirement yourself in addition to passing output checks. SQL sessions load the bundled SQLite module.</p><p>The browser does not provide a normal persistent desktop filesystem, live HTTP access for the fixture challenges, a web server, or interactive input(). Use VS Code for the full labs. A successful browser check and a completed local lab are separate kinds of evidence.</p><h2>3. Set up a local project on Windows</h2><ol><li>Install Python 3 and VS Code if needed; install the Python extension published by Microsoft.</li><li>Extract a lab ZIP into a new practice folder. Open that folder in VS Code.</li><li>Open Terminal → New Terminal. Run <code>py --version</code>. If Python is available only as <code>python</code>, use that launcher for environment creation instead.</li><li>Create a project environment with <code>py -m venv .venv</code>.</li><li>Use the environment directly: <code>.venv\\Scripts\\python --version</code>. In VS Code run Python: Select Interpreter and select this project’s .venv.</li><li>Run the included tests using <code>.venv\\Scripts\\python -m unittest -v</code>. They start red until you implement the scaffold.</li><li>Run your own entry point with <code>.venv\\Scripts\\python main.py</code> after you create it. The kit supplies core.py and test_core.py; the full application is yours to build.</li></ol><p>In macOS/Linux, create the environment with <code>python3 -m venv .venv</code> and use <code>.venv/bin/python</code> for the following commands. Directly invoking the environment avoids activation-script differences.</p><h2>4. Add libraries only when the lab needs them</h2><pre>.venv\\Scripts\\python -m pip install pytest
.venv\\Scripts\\python -m pytest -q

# Later, for HTTP and API labs:
.venv\\Scripts\\python -m pip install requests "fastapi[standard]" httpx
.venv\\Scripts\\python -m fastapi dev main.py</pre><p>Use these commands in your project terminal, not inside the Python prompt marked &gt;&gt;&gt;. Substitute .venv/bin/python on macOS/Linux. Install into the same interpreter you run. Record required dependencies in your project, and verify the README from a clean environment. Paid subscriptions and course certificates are not required for this path.</p><h2>5. Use small checkpoints in Git</h2><pre>git init
git status
git add core.py test_core.py README.md .gitignore
git diff --staged
git commit -m "Add the first tested core behavior"
git switch -c improve-validation</pre><p>Commit named source files deliberately and inspect the diff. Do not commit .venv, local databases, credentials, or generated personal data. Week 13 teaches staging, branches, and collaboration in depth; start recording small safe checkpoints now.</p><h2>6. Debug with a question, not random edits</h2><ol><li>Write the input, expected result, and actual result.</li><li>Reduce the input until the failure is easy to trace.</li><li>Read the last line of the error, then locate the relevant line in your file.</li><li>Inspect the variables with a print or breakpoint and test one hypothesis.</li><li>Preserve the failing example as a test after you fix it.</li></ol><a class="btn" href="#unit/1">Begin the first handbook →</a></article><aside><section class="card lab-panel"><h2>A realistic definition of confidence</h2><p>You can start a small unfamiliar task, clarify its rules, implement a coherent solution, use documentation, debug failures, test boundaries, and explain what you built. You will still look things up.</p><p>Keep three evidence types: independent function attempts, finished local labs, and changes to existing code. The <a href="#readiness">readiness page</a> helps you track these without pretending a score can certify them.</p><h3>Your first session</h3><ol><li>Read week 1.</li><li>Predict and run its worked example.</li><li>Open “Your first small win.”</li><li>Write the function and run checks.</li><li>Explain it, then save a backup.</li></ol><a class="btn light" href="#settings">Progress & backup →</a></section><section class="card lab-panel" style="margin-top:18px"><h2>A small programming glossary</h2>${[['Value','A piece of data such as 3, "Halo", True, or None.'],['Type','The kind of a value and the operations it supports.'],['Variable','A name bound to a value; assignment does not automatically copy an object.'],['Expression','Code that produces a value.'],['Statement','An instruction, such as assignment or return.'],['Function','Named reusable behavior with inputs, a result, and possibly effects.'],['Parameter / argument','A parameter is a name in a definition; an argument is a value supplied in a call.'],['Return / print','Return passes a result to a caller; print displays output.'],['Loop','Repeats a block over values or while a condition holds.'],['Collection','A structure holding values, such as a list, dict, set, or tuple.'],['Mutation','Changing an existing object rather than creating a separate result.'],['Exception','An execution failure that can be raised and handled.'],['Module / package','A module organizes Python code; a package organizes importable modules.'],['Dependency','A component your code relies on, including a library or storage adapter.'],['Test / fixture','A test checks a promised behavior; a fixture supplies repeatable setup data.'],['API / contract','An interface and the rules callers can depend on.'],['Invariant','A condition that must stay true throughout an operation.'],['Refactor','Change structure while preserving promised behavior.'],['Regression','A previously working behavior that breaks after a change.'],['Complexity','How time or extra storage grows with input size.']].map(([term,definition])=>`<dl><dt>${term}</dt><dd>${definition}</dd></dl>`).join('')}</section></aside></div>`;}
async function runWorkedExample(week){const u=handbook.units.find(x=>x.week===week),button=document.querySelector('[data-course-action="example"]');if(!u||!button||button.disabled)return;stopRun();button.disabled=true;$('#example-output').textContent='Loading Python and running the example…';worker=new Worker('runner.js?v='+FORGE_VERSION);runTimeout=setTimeout(()=>{stopRun();button.disabled=false;if($('#example-output'))$('#example-output').textContent='Python took too long. Try again after checking your connection.';},90000);worker.onmessage=({data})=>{if(data.type==='ready'){clearTimeout(runTimeout);runTimeout=setTimeout(()=>{stopRun();button.disabled=false;if($('#example-output'))$('#example-output').textContent='Stopped after 8 seconds.';},8000);}else if(data.type==='result'||data.type==='error'){stopRun();button.disabled=false;if($('#example-output'))$('#example-output').textContent=data.type==='error'?data.message:(data.data.error||data.data.stdout||'The example produced no printed output.');}};worker.onerror=()=>{stopRun();button.disabled=false;if($('#example-output'))$('#example-output').textContent='Could not run Python. Try again.';};worker.postMessage({code:u.worked.code,name:'',cases:[],packages:week===16?['sqlite3']:[]});}
document.addEventListener('click',e=>{const element=e.target.closest('[data-course-action]');if(element?.dataset.courseAction==='example')runWorkedExample(Number(element.dataset.week));});
document.addEventListener('change',e=>{const key=e.target.dataset.lab;if(key){state.labChecks[key]=e.target.checked;save();}});
document.addEventListener('click',e=>{const dismiss=e.target.closest('[data-notice-dismiss]');if(dismiss)dismissNotice(dismiss.dataset.noticeDismiss);const el=e.target.closest('[data-safety]');if(!el)return;const action=el.dataset.safety,key=el.dataset.recoveryKey;if(action==='reload')location.reload();if(action==='restore-snapshot')restoreSnapshot(Number(el.dataset.snapshot));if(action==='download-recovery')download('forge-progress-recovery-'+(key.split('-').pop())+'.json',localStorage.getItem(key)||'','application/json');if(action==='delete-recovery'&&confirm('Delete this recovery copy? This cannot be undone.')){localStorage.removeItem(key);route();}});
document.addEventListener('input',e=>{if(e.target.dataset.labNotes){state.labNotes[e.target.dataset.labNotes]=e.target.value;save();}if(e.target.dataset.evidence){state.evidence[e.target.dataset.evidence]=e.target.value;save();}});
